--what is the total revenue generated by male vs female.
select 
	gender,sum(purchase_amount)
from
	customertable
group by
	gender;

--which customer used a discount but still spent more than the avg purchase amt?
select
	customer_id,purchase_amount
from
	customertable 
where 
	discount_applied = 'Yes' and
	purchase_amount >
	(
		Select
			avg(purchase_amount) as amt
		from
			customertable 
	) ;

-- which are the top 5 products with highest avg review rating?
select 
	item_purchased, Round(avg_rating::numeric,2) AS avg_rating
from
	(
		select 
			item_purchased, avg(review_rating) as avg_rating
		from
			customertable
		group by
			item_purchased
		order by avg_rating desc
	) as t 
limit 5 ;
 --or
 select 
 	item_purchased, Round(avg_rating::numeric, 2)
 from
	 (
		select item_purchased,
		AVG(review_rating) as avg_rating,
		ROW_NUMBER() over (order by AVG(review_rating) desc) as rt
		from customertable
		group by 
			item_purchased
	) AS t
where rt <= 5 ;
	
-- Compare the avg purchase amt btw standard and express shipping.
select 
	MAX(p_amt::numeric) FILTER (where shipping_type = 'Express')
	- MAX(p_amt::numeric) FILTER ( where shipping_type = 'Standard') as diff
from
	(
		Select 
			shipping_type,
			AVG(purchase_amount) as p_amt
		from
			customertable
		group by
			shipping_type
	) as T;

--Do subscribed customers spend more ? Compare avg spent and total revenue btw subscribers and non subscribers?
Select 
	subscription_status,Count(customer_id) as t_cust, Round(avg(purchase_amount),2) as avg_amt , 
	   Round(sum(purchase_amount),2) as ttl_amt
from
	customertable
group by
	subscription_status ;

-- which 5 products have the highest percentage of purchases with discount applied/
--wrong

Select
		item_purchased, Round(per_amt,2),rn
from
	(
		Select 
				item_purchased, Count(*) Filter (Where discount_applied = 'Yes') * 100 /Count(*) AS per_amt,
				Row_number() over (order by Count(*) Filter (Where discount_applied = 'Yes') * 100 /Count(*) desc) as rn
		from 
				customertable
		group by
				item_purchased	
	) AS t
where 
		rn<=5 ;

		--correct
SELECT
    item_purchased,
    ROUND(
        COUNT(*) FILTER (
            WHERE discount_applied = 'Yes'
        ) * 100.0 / COUNT(*),
        2
    ) AS discount_percentage
FROM customertable
GROUP BY item_purchased
ORDER BY discount_percentage DESC
LIMIT 5;

--Segment customers into new , returning, and loyal based on their total number of previous purchases, and show the count of each segment.
Select
	customer, count(customer_id)
From
	(
Select customer_id,
	Case 
	when previous_purchases = 1 then 'New'
	when previous_purchases >=2 and previous_purchases<=10 then 'Returning'
	when previous_purchases >10 then 'Loyal'
	End As customer 
from
	customertable
	)
group by 
	customer ;

--what are the top 3 most purchased products within each category?
Select
	category, item_purchased,rn
From
	(
		Select
			category, item_purchased,count(*) as c,
			Row_number() over(partition by category 
								ORDER by count(*) desc) as rn
		from
			customertable
		group by
			category, item_purchased
		
	) AS t
where
	rn<=3 ;

--Are customers who re repeat buyers(more than 5 previous purchase) also likely to subscribe?
Select
	subscription_status , count(Customer_id)
from
	customertable
where
	previous_purchases > 5 
group by
	subscription_status ;

-- What is the revenue contribution of each age group?
Select
	age_group, 	Sum(purchase_amount)
from
	customertable
group by age_group;






































